function parseDays(s: string): Result<number> {
  const n = Number(s);
  if (!Number.isInteger(n)) return { ok: false, error: "not a whole number" };
  if (n < 1 || n > 60) return { ok: false, error: "out of range" };
  return { ok: true, value: n };
}
console.log(["x","0","60"].map((s) => { const r = parseDays(s); return r.ok ? r.value : r.error; }).join(" | "));

